                <iframe :src="originalUrl" :title="`${current.title}, original page`" sandbox="allow-scripts allow-same-origin allow-popups allow-popups-to-escape-sandbox allow-forms" allow="autoplay 'none'" referrerpolicy="same-origin"></iframe>
