              <h2 v-else-if="isClosing"><span :lang="translationSource" dir="auto">{{ closingLabel }}</span><small v-if="translatedClosingLabel" :lang="translationTarget" dir="auto">{{ translatedClosingLabel }}</small></h2>
              <h2 v-else-if="narrativeRoom"><ExhibitionTitle :text="narrativeRoom.title"/><small v-if="translated(`section.${narrativeRoom.sectionIndex}`)">{{ translated(`section.${narrativeRoom.sectionIndex}`) }}</small></h2>
              <h2 v-else class="exhibition-entrance-title"><ExhibitionTitle :text="exhibition.title"/><small v-if="translated('title')">{{ translated('title') }}</small></h2>
              <p v-if="translationError" class="exhibition-translation-error" role="status">{{ translationError }}</p>
              <div class="exhibition-story-prose" ref="prose" :lang="translationVisible ? translationTarget : translationSource" :dir="translationVisible && /^(ar|he|fa|ur|ps|sd)(-|$)/.test(translationTarget) ? 'rtl' : 'auto'">
                <ol v-if="isCitations" class="exhibition-citations">
                  <li v-for="(item, index) in exhibition.citations.items" :key="item.id"><button ref="citationLinks" data-exhibition-control type="button" @click="openCitation(index)"><span class="exhibition-citation-number">{{ String(index + 1).padStart(2, '0') }}</span><span><small>{{ item.page }}</small>{{ item.title }}</span></button></li>
                </ol>
                <template v-else-if="isClosing"><ExhibitionSpokenText :text="translated('closing.text') || exhibition.closing.text" :language="audioLanguage" :active="audioProgressKey === 'closing'" :word-index="audioWordIndex"/><button v-if="compact && shareId && (isPublic || canPublish)" data-exhibition-control class="exhibition-notes-inline" type="button" @click="$refs.guestbook?.open()"><svg data-exhibition-icon viewBox="0 0 24 24" aria-hidden="true"><path d="M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1Zm0 0v15"/></svg><span>{{isPublic?'Visitors’ notes':'Make public'}}</span><span aria-hidden="true">↗</span></button></template>
                <template v-else-if="narrativeRoom">
                  <ExhibitionSpokenText v-if="narrativeRoom.introduction" class="exhibition-room-intro" :text="translated(`intro.${narrativeRoom.sectionIndex}`) || narrativeRoom.introduction" :language="audioLanguage" :active="audioProgressKey === `${narrativeRoom.sectionIndex}/intro`" :word-index="audioWordIndex"/>
                  <ExhibitionSpokenText v-for="passage in readingPassages" :key="passage.key" :text="passage.text" :language="audioLanguage" :active="audioProgressKey === `${narrativeRoom.sectionIndex}/${passage.blockIndex}/${passage.paragraph}`" :word-index="audioWordIndex" :data-narrative-key="passage.key" :data-narrative-position="passage.blockIndex" :class="{ 'is-highlighted': visitStep?.key === passage.key && visitStep?.highlight, 'is-reading': visitStep?.key === passage.key }" :aria-current="visitStep?.key === passage.key ? 'step' : null"/>
                </template>
                <template v-else><ExhibitionSpokenText :text="translated('summary') || exhibition.dek" :language="audioLanguage" :active="audioProgressKey === 'entrance'" :word-index="audioWordIndex"/></template>
              </div>
              <div v-if="!narrativeRoom && !isClosing && !isCitations" class="exhibition-reading-tools">

              <ViewSummaryAudio v-if="shareId && !narrativeRoom && !isClosing" class="exhibition-summary-audio" :share-id="shareId" :audio-src="view.audio?.src || ''" :language="translationVisible ? translationTarget : ''" :source-language="translationSource" :translation-pending="translationLoading" />
              </div>
              <div v-if="storyWork && narrativeRoom && !isClosing && !isCitations" class="exhibition-story-actions">
                <span class="exhibition-selected-work">{{ storyWork.title }}</span>
                <button data-exhibition-control ref="lookCloser" type="button" class="exhibition-look" @click="openPreview">Open the work <span aria-hidden="true">↗</span></button>
              </div>
              <button data-exhibition-control v-if="!narrativeRoom" ref="begin" class="exhibition-begin" type="button" :disabled="!exhibition.rooms.length" @click="goStep(0)">Begin the visit <span aria-hidden="true">→</span></button>
