          </transition>
        </aside>
        <ViewGuestbook v-if="shareId" v-show="isClosing && !inspecting" ref="guestbook" :hide-invitation="compact" :is-public="isPublic" :can-publish="canPublish" @publish="$emit('publish')" class="exhibition-guestbook" exhibition :share-id="shareId" :title="view.title" @open="openGuestbook" @close="notesOpen = false" @change="updateNotes" />
        <div v-if="hoveredWork && !inspecting && !guideOpen" class="exhibition-object-feedback" aria-live="polite">
          <figure v-if="hoveredWork.place" class="exhibition-place-preview" :style="placePreviewStyle">
            <img :key="hoveredWork.place.en" :src="hoveredWork.place.preview" :alt="hoveredWork.place.label" decoding="async" />
            <figcaption>{{ hoveredWork.place.label }}</figcaption>
          </figure>
          <span v-else-if="hoveredWork.scrollable && !hasScrolledWork" class="exhibition-object-hint" :style="scrollHintStyle">Scroll to read</span>
        </div>
        <footer v-show="!inspecting" class="exhibition-footer">
          <div class="exhibition-footer-side">
            <button data-exhibition-control ref="guideTrigger" class="exhibition-guide-trigger" type="button" :aria-expanded="guideOpen" @click="toggleGuide"><svg data-exhibition-icon viewBox="0 0 22 22" aria-hidden="true"><path d="m3 5 5-2 6 2 5-2v14l-5 2-6-2-5 2zM8 3v14M14 5v14" /></svg><span>The visit</span></button>
            <span v-if="narrativeRoom" class="exhibition-count">{{ String(narrativeRoomIndex + 1).padStart(2, '0') }} <span>/</span> {{ String(exhibition.rooms.length).padStart(2, '0') }}</span>
          </div>
          <div class="exhibition-audio-position">
            <ExhibitionAudio v-if="shareId" :share-id="shareId" :cue="audioCue" :text="audioText" :language="translationVisible ? translationTarget : ''" :busy="audioBusy" @progress="trackNarration" @complete="continueNarration" />
          </div>
          <div class="exhibition-footer-mode">
            <nav v-if="narrativeRoom" class="exhibition-navigation" aria-label="Guided visit">
              <button data-exhibition-control type="button" aria-label="Previous passage" @click="goStep(visitStepIndex - 1)"><span aria-hidden="true">←</span><span class="exhibition-navigation-label">Previous</span></button>
              <span class="exhibition-navigation-divider" aria-hidden="true"></span>
              <button data-exhibition-control type="button" :aria-label="visitStepIndex >= exhibition.steps.length - 1 ? 'Return to the hall' : 'Next passage'" @click="visitStepIndex >= exhibition.steps.length - 1 ? leave() : goStep(visitStepIndex + 1)">{{ visitStepIndex >= exhibition.steps.length - 1 ? 'Hall' : 'Next' }} <span aria-hidden="true">→</span></button>
            </nav>
            <button v-else-if="compact" data-exhibition-control class="exhibition-mobile-start" type="button" @click="goStep(0)">Start <span aria-hidden="true">→</span></button>
            <div v-else class="exhibition-walk-hint" aria-label="Use the arrow keys to walk freely">
              <span class="exhibition-walk-keys" aria-hidden="true"><kbd class="is-up">↑</kbd><kbd class="is-left">←</kbd><kbd class="is-down">↓</kbd><kbd class="is-right">→</kbd></span>
              <span>Walk freely</span>
            </div>
          </div>
        </footer>
      </template>
      <ViewGenerationNotice v-if="!showcaseFrame" />
      <MusicControls v-if="musicReady" inline trigger-selector="[data-exhibition-music]" panel-id="exhibition-music-panel" />
    </dialog>
  </Teleport>
</template>

<script>
import { ensureHandwritingFonts } from '../../utils/siteHandwriting';
import { readingSheetStops, settleReadingSheet } from '../../utils/exhibitionReadingSheet';
import { beginExhibitionTheme } from '../../utils/exhibitionTheme';
import '../../assets/css/exhibition-controls.css';
import { coverViewTransition, revealViewTransition } from '../../utils/viewPresentationTransition';
import ExhibitionTitle from './ExhibitionTitle.vue';
import ViewPresentationControl from './ViewPresentationControl.vue';
import { createViewExhibition, exhibitionStopForPosition, exhibitionStepForPosition, exhibitionStepForWork, exhibitionPlaces } from '../../utils/viewExhibition';
import { sourceRouteTarget } from '../../utils/viewSourceTarget';
import { initImageEnlargement } from '../../utils/imageEnlargement';
import { decodeViewText } from '../../utils/viewText';
import { exhibitionNarrationBusy, exhibitionNarrationCue } from '../../utils/exhibitionGuideAudio';
import { bindExhibitionKeyboard } from '../../utils/exhibitionKeyboard';
import { viewClosingLabel } from '../../utils/viewClosing';
import exhibitionGuides from '../../data/exhibitionGuides.json';
import ViewGuestbook from './ViewGuestbook.vue';
import MusicControls from '../ui/MusicControls.vue';
import ViewTranslationControl from './ViewTranslationControl.vue';
import ExhibitionAudio from './ExhibitionAudio.vue';
import ExhibitionSpokenText from './ExhibitionSpokenText.vue';
import ExhibitionWalkPad from './ExhibitionWalkPad.vue';
import ViewSummaryAudio from './ViewSummaryAudio.vue';
import JourneyTab from '../JourneyTab.vue';
import AiViewTerm from '../ui/AiViewTerm.vue';
import ViewOriginalBlock from './ViewOriginalBlock.vue';
import ViewSourceBlock from './ViewSourceBlock.vue';
import MuseumOrientationHint from './MuseumOrientationHint.vue';
import MuseumSiteMenu from './MuseumSiteMenu.vue';
import ViewGenerationNotice from './ViewGenerationNotice.vue';
import { rememberViewVisit, completeViewVisit, updateMuseumSession, museumSession } from '../../utils/viewMuseumSession';

export default {
  name: 'ViewExhibition',
  components: { ExhibitionTitle, ViewPresentationControl, MuseumSiteMenu, MuseumOrientationHint, MusicControls, ViewTranslationControl, ViewGuestbook, ExhibitionAudio, ExhibitionSpokenText, ExhibitionWalkPad, ViewSummaryAudio, JourneyTab, AiViewTerm, ViewOriginalBlock, ViewSourceBlock, ViewGenerationNotice },
  props: {
    translationSource: { type: String, default: '' }, translationTarget: { type: String, default: 'en' },
    translations: { type: Object, default: () => ({}) }, translationAvailable: Boolean, translationVisible: Boolean, translationLoading: Boolean, translationError: { type: String, default: '' },
    showcase: Boolean,
    showcaseLinked: Boolean,
    showcaseLoop: Boolean,
    showcaseReturnHall: Boolean,
    showcaseControls: Boolean,
    showcaseChannel: { type: String, default: '' },
    showcaseFrame: Boolean,
    createdAt: {type:[String,Number],default:null},
    isPublic: Boolean, canPublish: Boolean, shareId: { type: String, default: '' },
    view: { type: Object, required: true }, sources: { type: Map, required: true },
    currentSources: { type: Map, default: () => new Map() },
    initialPosition: { type: Object, default: null },
  },
  emits: ['leave-start', 'close', 'select-translation', 'publish'],
  data: () => ({ exitTarget: 'hall', exitPath: '', compact: false, readingMode: 'peek', readingHeight: null, readingWidth:null, selectedPhoto: null, cameraTravelling: false, notesFocused: false, musicReady: false, musicPlaying: false, notesOpen: false, ready: false, error: false, dark: false, activeIndex: -1, visitStepIndex: -1, narrativeRoomIndex: -1, audioProgressKey:'', audioWordIndex:-1, scrolledWorks: new Set(), selectedPlace: '', inspecting: false, guideOpen: false, orientationActive:false, orientationIndex:0, orientationTargetStyles:[], orientationCardStyle:{}, leaving: false, originalUrl: '', backdropPress: null, visited: false, hoveredWork: null, showcasePaused: false, readerPosition: { x: 0, z: 6, roomIndex: -1 } }),
  computed: {
    floorplanViewBox() { const b=this.exhibition.architecture.bounds; return `${b.minX-2} ${b.minZ-2} ${b.width+4} ${b.depth+4}`; },
    closingLabel() { return viewClosingLabel(this.translationSource, this.exhibition.closing?.text); },
    translatedClosingLabel() { return this.translationVisible ? viewClosingLabel(this.translationTarget, '', this.translated('closing.label')) : ''; },
    hasScrolledWork() { return this.scrolledWorks.has(this.hoveredWork?.index); },
    isCitations() { return this.visitStep?.kind === 'citations'; },
    isClosing() { return this.visitStep?.kind === 'closing'; },
    exhibition() {
      const guide = exhibitionGuides[this.shareId];
      return createViewExhibition(this.view, id => this.sources.get(id), guide?.question === this.view.question ? guide : null);
    },
    audioCue() {
      if (this.translationVisible && this.visitStep?.kind === 'passage' && !this.readingPassages.some(p => p.key === this.visitStep.key)) return null;
      return exhibitionNarrationCue(this.exhibition, this.visitStepIndex);
    },
    audioBusy() { return exhibitionNarrationBusy(this); },
    audioLanguage() { return this.translationVisible ? this.translationTarget : this.translationSource; },
    audioText() {
      const key=this.audioCue?.key;if(!key)return '';
      if(key==='entrance')return this.translated('summary')||this.exhibition.dek||'';
      if(key==='closing')return this.translated('closing.text')||this.exhibition.closing?.text||'';
      if(key.endsWith('/intro'))return this.translated(`intro.${this.visitStep?.sectionIndex}`)||this.narrativeRoom?.introduction||'';
